                    var number = methodCount++;
                    EmitMethod(number, wrapper, new Dictionary<IParser, string>() { [parser] = inner });
                    return $"P{number}";
                });

            foreach (var (parser, number) in pending)
            {
                EmitMethod(number, parser, lookup);
            }

            return lookup[root];
        }

