            method.Append($"            // {Describe(parser)}\n");
            method.Append($"            public bool P{number}(int pos, out int end, out {TypeName(parser.ResultType)} value)\n");
            method.Append("            {\n");
            method.Append(body);
            method.Append("            }\n");
            methods[number] = method.ToString();
